/* Reproducible geometry-only derivative of a public licensed photogrammetry scan.
 * Download the source URL in README.md separately. No network access in this tool.
 */
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {parseModelPreview} from '../../../web/model-viewer.mjs';
const source=process.argv[2];if(!source)throw Error('Usage: node tests/fixtures/3d/derive-public-scan.mjs /path/to/IridescenceAbalone.glb');
const original=await readFile(source),hash=bytes=>createHash('sha256').update(bytes).digest('hex');
if(hash(original)!=='d15ab000d3b04f177e101b2a36aacbf1c99490fc9bfe3868d481d75736946bab')throw Error('Source changed. Review official upstream provenance and license before regenerating.');
const model=parseModelPreview(original,'IridescenceAbalone.glb'),directory=new URL('./',import.meta.url);
const lines=['ply','format ascii 1.0','comment Real photogrammetry scan: Abby Crawford 2015, CC BY 4.0','comment Geometry-only derivative. Materials by Eric Chadwick 2023 removed.','comment Source and changes: README.md','element vertex '+model.vertexCount,'property float x','property float y','property float z','element face '+model.triangleCount,'property list uchar uint vertex_indices','end_header'];
for(let i=0;i<model.positions.length;i+=3)lines.push(Array.from(model.positions.subarray(i,i+3)).map(n=>n.toPrecision(9)).join(' '));
for(let i=0;i<model.indices.length;i+=3)lines.push('3 '+Array.from(model.indices.subarray(i,i+3)).join(' '));
const ply=Buffer.from(lines.join('\n')+'\n');await writeFile(new URL('abalone-scan.geometry.ply',directory),ply);
// Flattened, uncompressed, static GLB of exactly the same transformed vertices/faces.
const binary=Buffer.alloc(model.positions.length*4+model.indices.length*4);for(let i=0;i<model.positions.length;i++)binary.writeFloatLE(model.positions[i],i*4);for(let i=0;i<model.indices.length;i++)binary.writeUInt32LE(model.indices[i],model.positions.length*4+i*4);
const document={asset:{version:'2.0',copyright:'Abby Crawford (2015), Eric Chadwick (2023), CC BY 4.0. Geometry-only derivative; see README.md.'},scene:0,scenes:[{nodes:[0]}],nodes:[{mesh:0}],meshes:[{primitives:[{attributes:{POSITION:0},indices:1}]}],buffers:[{byteLength:binary.length}],bufferViews:[{buffer:0,byteOffset:0,byteLength:model.positions.length*4},{buffer:0,byteOffset:model.positions.length*4,byteLength:model.indices.length*4}],accessors:[{bufferView:0,componentType:5126,count:model.vertexCount,type:'VEC3'},{bufferView:1,componentType:5125,count:model.indices.length,type:'SCALAR'}]};
const text=Buffer.from(JSON.stringify(document)),json=Buffer.concat([text,Buffer.alloc((4-text.length%4)%4,32)]),glb=Buffer.alloc(12+8+json.length+8+binary.length);glb.writeUInt32LE(0x46546c67,0);glb.writeUInt32LE(2,4);glb.writeUInt32LE(glb.length,8);glb.writeUInt32LE(json.length,12);glb.writeUInt32LE(0x4e4f534a,16);json.copy(glb,20);glb.writeUInt32LE(binary.length,20+json.length);glb.writeUInt32LE(0x004e4942,24+json.length);binary.copy(glb,28+json.length);await writeFile(new URL('abalone-scan.geometry.glb',directory),glb);
const provenance={name:'IridescenceAbalone geometry-only scan fixture',capture:'photogrammetry (public shell scan, not an apartment or LiDAR)',source:'https://raw.githubusercontent.com/KhronosGroup/glTF-Sample-Assets/main/Models/IridescenceAbalone/glTF-Binary/IridescenceAbalone.glb',sourceReadme:'https://github.com/KhronosGroup/glTF-Sample-Assets/blob/main/Models/IridescenceAbalone/README.md',sourceSha256:hash(original),sourceBytes:original.length,license:'CC BY 4.0',licenseUrl:'https://creativecommons.org/licenses/by/4.0/',copyright:['2015 Abby Crawford: everything','2023 Eric Chadwick: materials'],changes:'Removed materials, images, normals, UVs and metadata; applied source static scene transform. Preserved every mesh vertex and triangle. Exported geometry-only ASCII PLY and uncompressed GLB. No resampling or invented geometry.',declaredUnits:null,vertexCount:model.vertexCount,triangleCount:model.triangleCount,files:{'abalone-scan.geometry.ply':{bytes:ply.length,sha256:hash(ply)},'abalone-scan.geometry.glb':{bytes:glb.length,sha256:hash(glb)}}};await writeFile(new URL('abalone-scan.provenance.json',directory),JSON.stringify(provenance,null,2)+'\n');console.log(JSON.stringify({directory:fileURLToPath(directory),vertexCount:model.vertexCount,triangleCount:model.triangleCount,files:provenance.files}));
